import React, { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./addToCartSuccess.css";

const AddToCartSuccessModal = ({ open, onClose }) => {
  const navigate = useNavigate();

  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "auto";
  }, [open]);

  if (!open) return null;

  return (
    <div className="cart-success-overlay">
      <div className="cart-success-card">
        <div className="success-icon">
          <i className="fas fa-shopping-cart"></i>
          <span className="check">✔</span>
        </div>

        <h3>Added to cart!</h3>
        <p>Your product has been added successfully.</p>

        <div className="success-actions">
          <button
            className="btn-outline"
            onClick={() => {
              onClose();
              navigate("/cart");
            }}
          >
            View Cart
          </button>

          <button className="btn-primary" onClick={onClose}>
            Continue Shopping
          </button>
        </div>
      </div>
    </div>
  );
};

export default AddToCartSuccessModal;
